NAME = 'NlCanisius1939: Petrus Canisius Translation'
BOOK = 'Song of Solomon'

CHAPTERS = {
    1: {
        1: 'Drenk mij met de kussen van uw mond; Want uw liefde is zoeter dan wijn.',
        2: 'Heerlijk is de geur van uw balsem, Uw naam is het kostbaarst aroom. Daarom hebben de meisjes u lief.',
        3: 'Neem mij mede, laat ons vluchten; Want de koning heeft mij in zijn vertrekken gebracht! Wij willen juichen, in u ons verblijden, Uw liefde roemen, hoger dan wijn, Terecht beminnen zij u!',
        4: 'Wel ben ik donker, Maar toch nog schoon, Jerusalems dochters: Als de tenten van Kedar, De paviljoenen van Sjalma.',
        5: 'Let er niet op, dat ik zwart ben, En van de zon ben verbrand; Want de zonen van mijn moeder waren boos op mij, En lieten mij de wijngaarden bewaken….Maar mijn eigen wijngaard bewaakte ik niet!',
        6: 'Bericht mij toch, mijn zielsbeminde, Waar ge uw kudde laat weiden, Waar ge ze in de middag laat rusten? Want waarom zou ik gaan zwerven Bij de kudden uwer vrienden?',
        7: 'Als ge het niet weet, Schoonste der vrouwen, Volg dan het spoor van de kudde, En hoed uw geiten Bij de tenten der herders.',
        8: 'Met het span van Farao’s wagens Vergelijk ik u, liefste;',
        9: 'Hoe bekoorlijk uw wangen tussen de hangers, Uw hals in de snoeren.',
        10: 'Gouden hangers laten we u maken, Met plaatjes van zilver.',
        11: 'Zolang de koning in zijn harem verbleef, Straalde mijn nardus haar geur.',
        12: 'Want mijn beminde is mij een bundeltje mirre, Dat op mijn boezem blijft rusten;',
        13: 'Mijn beminde is mij een cyper-tros, Van Engédi’s gaarden.',
        14: 'Wat zijt ge verrukkelijk, mijn liefste, Uw ogen zijn duiven.',
        15: 'Wat zijt ge verrukkelijk schoon, mijn beminde Ons rustbed is in het groen!',
        16: 'De binten van ons paleis zijn ceders, Onze wanden cypressen.',
    },
    2: {
        1: 'Maar ik ben een crocus van Sjaron, Een lelie der dalen!',
        2: 'Als een lelie tussen de doornen, Is mijn liefste onder de meisjes.',
        3: 'Als een appelboom tussen de bomen in het woud, Is mijn beminde onder de jongemannen; Ik smacht er naar, in zijn schaduw te zitten, Zijn vrucht is zoet voor mijn mond.',
        4: 'Brengt mij naar het huis van de wijn, Ontplooit over mij de standaard der liefde;',
        5: 'Verkwikt mij met druivenkoeken, Versterkt mij met appels. Want ik ben krank, Ben krank van liefde!',
        6: 'Zijn linker moet rusten onder mijn hoofd, Zijn rechter houde mij omstrengeld!',
        7: 'Ik bezweer u, Jerusalems dochters, Bij de gazellen en de hinden in het veld: Wekt en lokt de liefde niet, Voordat het haar lust! ….',
        8: 'Maar hoor, mijn beminde! Zie, hij komt! Hij springt over de bergen, Hij huppelt over de heuvels.',
        9: 'Mijn beminde gelijkt een gazel, Of het jong van een hert. Zie, daar staat hij reeds Achter onze muur. Hij staart door het venster, En blikt door de tralies;',
        10: 'Mijn beminde heft aan, En spreekt tot mij! Sta op, mijn geliefde, Mijn schone, kom mede!',
        11: 'Want zie, de winter is voorbij, De regen is voorgoed verdwenen.',
        12: 'De bloemen prijken op het land, Men hoort de duiven al kirren;',
        13: 'De vijg kleurt reeds zijn jonge vrucht, De wingerds bloeien en geuren. Sta op, mijn geliefde, Mijn schone, kom mede;',
        14: 'Mijn duifje in de spleten der rotsen, In de holen der klippen! Laat mij zien uw gelaat, Laat mij horen uw stem; Want uw stem is zo zoet, Uw gelaat is zo lief.',
        15: 'Vangt ons de jakhalzen De kleine vossen, Die de tuinen vernielen, Ofschoon onze wijngaard al bloeit.',
        16: 'Want mijn beminde is mijn, en ik van hem: Hij is het, die in de leliën weidt,',
        17: 'Totdat de dag is afgekoeld En de schaduwen vlieden! Blijf hier, mijn beminde, En doe zoals de gazel Of het jong van het hert Op de balsembergen!',
    },
    3: {
        1: 'Des nachts op mijn sponde Zocht ik naar mijn zielsbeminde; Ik zocht naar hem, Maar vond hem niet!',
        2: 'Ik wil opstaan, rondgaan door de stad, Mijn zielsbeminde zoeken op straten en pleinen; Ik zocht naar hem, Maar vond hem niet!',
        3: 'Zo troffen mij de wachters der stad bij hun rondgang: "Hebt gij mijn zielsbeminde gezien?"',
        4: 'Maar nauwelijks was ik hun voorbij, Of ik vond mijn zielsbeminde terug. Ik greep hem vast, En liet hem niet los, Tot ik hem gebracht had in het huis van mijn moeder, In de kamer van haar, die mij baarde.',
        5: 'Ik bezweer u, Jerusalems dochters, Bij de gazellen en de hinden in het veld: Wekt en lokt de liefde niet, Voordat het haar lust! ….',
        6: 'Maar wat stijgt daar op uit de steppe, Aan een rookzuil gelijk, Geurend van mirre en wierook, Van allerlei kruiden der kramers?',
        7: 'Zie, het is de draagkoets van Salomon, Door zestig van Israëls helden omringd:',
        8: 'Allen omgord met het zwaard, En ten strijde geoefend; Iedereen met het zwaard op zijn heup, Om de vrees voor de nacht.',
        9: 'Koning Salomon heeft zich een draagkoets gemaakt Van Libanon-hout:',
        10: 'De stijlen liet hij van zilver maken, Haar leuning van goud, De zitting van purper, Met ebbenhout van binnen bekleed.',
        11: 'Jerusalems dochters, loopt uit, Gaat kijken, dochters van Sion: Het is koning Salomon met de kroon, Waarmee zijn moeder hem kroonde Op de dag van zijn huwelijk, Op de dag van de vreugde zijns harten!',
    },
    4: {
        1: 'Wat zijt ge verrukkelijk, mijn liefste: Uw ogen liggen als duiven achter uw sluier, Uw lokken zijn als een kudde geiten, Die neergolft van Gilads gebergte.',
        2: 'Uw tanden als een kudde, die pas is geschoren, En zo uit het bad; Die allen tweelingen hebben, Waarvan er geen enkel ontbreekt.',
        3: 'Als een band van purper uw lippen, Aanminnig uw mond; Als granatenhelften blozen uw wangen Door uw sluier heen.',
        4: 'Uw hals als de toren van David, Gebouwd met kantélen: Duizend schilden hangen er aan, Louter rondassen van helden.',
        5: 'Uw beide borsten twee welpen, Tweelingen van de gazel, die in de leliën weiden,',
        6: 'Totdat de dag is afgekoeld En de schaduwen vlieden. Ik wil naar de berg van mirre gaan En naar de heuvel van wierook;',
        7: 'Want alles is schoon aan u, liefste, Geen vlek op u! ….',
        8: 'Van de Libanon, mijn bruid, Met mij zijt ge van de Libanon gekomen, Hebt ge Amana’s top verlaten, De top van Senir en de Hermon: De holen der leeuwen, De bergen der panters.',
        9: 'Gij hebt mij betoverd, mijn zuster, bruid, Betoverd met één blik van uw ogen, Met één lijn van uw hals!.',
        10: 'Hoe schoon is uw liefde, mijn zuster, bruid, Hoe strelend uw minne meer dan de wijn, Hoe heerlijk uw geuren, lieflijker nog dan de balsem.',
        11: 'Van honingzoet druipen Uw lippen, o bruid; Honing en melk Zijn onder uw tong; De geur uwer kleren Is als Libanon-geur.',
        12: 'Een gegrendelde hof is mijn zuster, bruid, Een gesloten wel, Een verzegelde bron:',
        13: 'Uw lusthof is een paradijs van granaten, Met allerlei kostelijke vruchten, Met hennabloemen en nardusplanten,',
        14: 'Saffraan, kaneel en muskaat, Met wierookgewassen, mirre en aloë, En een keur van heerlijke balsem!',
        15: 'Een bron in de tuinen Een wel van levend water, Dat van de Libanon stroomt.',
        16: 'Waak op, noordenwind, Zuidenwind, kom! Waai door mijn hof, Laat zijn balsemgeur stromen: Opdat mijn beminde in zijn lusthof kome, Er zijn kostelijke vruchten mag smaken.',
    },
    5: {
        1: 'Ik kom in mijn hof, mijn zuster, bruid; Ik pluk er mijn mirre en balsem, Ik eet er mijn raat en mijn honing, Ik drink er mijn wijn en mijn melk! "Eet vrienden, en drinktl, En wordt dronken van liefde!"',
        2: 'Ik sluimerde, maar mijn hart was wakker: Daar hoorde ik mijn beminde kloppen! "Doe open, mijn zuster, Mijn liefste, mijn duifje, mijn schoonste; Want mijn hoofd is nat van de dauw, Mijn lokken zijn klam van de nacht."',
        3: '"Maar ik heb mijn kleed al uitgetrokken; Moet ik het nu dan weer aandoen? Ik heb mijn voeten al gewassen, Moet ik ze nu opnieuw gaan besmeuren?"',
        4: 'Maar mijn beminde stak reeds zijn hand Door de kier van de deur;',
        5: 'Ik stond op, om mijn beminde open te doen: Daar dropen mijn handen van mirre, Van vloeiende mirre mijn vingers Op de knop van de grendel.',
        6: 'Ik deed open voor mijn beminde…..Maar mijn beminde was heen, was verdwenen…..Ik zocht naar hem, ik vond hem niet, Ik riep, hij gaf mij geen antwoord. Ik verloor mijn bezinning, toen hij zo sprak En het stormde in mijn hart.',
        7: 'Weer troffen mij de wachters der stad bij hun rondgang, Ze sloegen mij en wondden mij; Mijn mantel namen ze mij af, De wachters der muren.',
        8: 'Ik bezweer u, Jerusalems dochters, Als gij mijn beminde vindt, Wat zult gij hem melden: Ach, dat ik krank ben van liefde!',
        9: 'Wat is uw beminde dan meer dan een ander, Schoonste der vrouwen; Wat is uw beminde dan meer dan een ander, Dat ge zó ons bezweert?',
        10: 'Mijn beminde is glanzend en blozend. Steekt boven tienduizenden uit;',
        11: 'Zijn hoofd het allerfijnste goud, Zijn lokken palmtakken, zwart als een raaf.',
        12: 'Zijn ogen als duiven Aan de waterbeken, Die zich baden in melk Aan de volle vijver gezeten.',
        13: 'Zijn wangen zijn als balsembedden, Waar geurige kruiden op groeien; Zijn lippen zijn lelies, En druipen van vloeiende mirre.',
        14: 'Zijn armen zijn gouden cilinders, Met Tarsjisjstenen bezet; Zijn lijf een kolom van ivoor, Met saffieren bedekt.',
        15: 'Zijn schenkels zijn zuilen van marmer, Op gouden voetstukken rustend; Zijn gestalte is als de Libanon, En machtig als ceders.',
        16: 'Zijn keel is vol zoetheid, Een en al kostelijk…. Zo is mijn beminde, zo is mijn vriend, Jerusalems dochters!',
        17: 'Maar waarheen is uw beminde gegaan, Schoonste der vrouwen; Waarheen is uw beminde geweken, Wij willen met u hem gaan zoeken!',
    },
    6: {
        1: 'Mijn beminde is naar zijn lusthof gegaan, Naar de balsembedden, Om in de lusthof te weiden En lelies te plukken.',
        2: 'Maar mijn beminde blijft mijn, en ik van hem: Hij is het, die in de leliën weidt, Totdat de dag is afgekoeld en de schaduwen vlieden!',
        3: 'Schoon zijt gij, mijn liefste Heerlijk als Tirsa Bekoorlijk als Jerusalem, Maar ook geducht als een leger.',
        4: 'Wend uw ogen van mij af, Want ze brengen mij in verwarring; Uw lokken zijn als een kudde geiten, Die neergolft van Gilad.',
        5: 'Uw tanden zijn als een kudde schapen, Zo juist uit het bad, Die allen tweelingen hebben Waarvan er geen enkel ontbreekt.',
        6: 'Als een band van purper uw lippen, Aanminnig uw mond; Als granatenhelften blozen uw wangen Door uw sluier heen.',
        7: 'Koninginnen zijn er zestig En bijvrouwen tachtig, Jonge meisjes ontelbaar: Maar mijn duifje, mijn schoonste is énig!',
        8: 'Zij was al enig voor haar moeder, De lieveling van haar, die haar baarde; Als de meisjes haar zagen, dan roemden ze haar. Koninginnen en bijvrouwen prezen haar.',
        9: 'Wie rijst daar op als het morgenrood, Schoon als de maan, En klaar als de zon, Maar ook geducht als een leger?',
        10: 'Naar de notenhof wilde ik gaan, Om de bloemen in het dal te aanschouwen, Om te zien, of de wijnstok al uitbot, De granaten al bloeien.',
        11: 'En zonder dat ik het wist, Hebt gij mij in de vorstelijke draagkoets gezet….',
        12: 'Terug, kom terug, Sjoelammiet; Terug, kom terug, wij willen u zien! Wat gaapt gij de Sjoelammietische aan, Als een zwaarddanseres?',
    },
    7: {
        1: 'Hoe sierlijk uw passen In de sandalen, vorstendochter; Uw wiegende heupen als snoeren, Door meesterhanden gemaakt.',
        2: 'Uw navel een welgerond bekken, Waarin geen wijn mag ontbreken; Uw lijf een tarweschelf, Van lelies omringd.',
        3: 'Uw beide borsten twee hertenwelpen, Tweelingen van een gazel;',
        4: 'Uw hals een toren van ivoor, Uw ogen als de vijvers van Chesjbon, Bij de poort der volkrijke stad; Uw neus als de Libanon-spits, Die naar Damascus ziet.',
        5: 'Het hoofd op u als de Karmel. Uw lokken als purper, In uw vlechten ligt een koning gevangen.',
        6: 'Wat zijt ge schoon, wat zijt ge bevallig, Een liefste vol bekoorlijkheid!',
        7: 'Uw slanke leest is als een palm, Uw borsten trossen van druiven.',
        8: 'Ik dacht: Ik wil de palm beklimmen, Zijn dadels grijpen. Uw borsten mogen voor mij zijn Als druiventrossen uit de wingerd; De geur van uw adem als appels,',
        9: 'Uw mond als de edelste wijn….Die rechtens naar mijn beminde stroomt, Maar afgeleefde lippen ontvliedt!',
        10: 'Neen, ik blijf van mijn beminde, En zijn verlangen gaat uit naar mij! ….',
        11: 'Ach kom, mijn beminde, Gaan wij uit naar het veld; Laat ons overnachten in dorpen, Gaan wij vroeg de wijngaarden in.',
        12: 'Laat ons zien, of de wijnstok al uitbot, Of de bloesems zijn opengegaan, Of de granaten al bloeien: Daar zal ik u mijn liefde schenken!',
        13: 'De liefdeappelen verspreiden hun geur, Boven onze deur hangen de kostelijkste vruchten, Jonge vruchten en oude: Ik spaarde ze voor u, mijn beminde!',
    },
    8: {
        1: 'Ach waart ge mijn broeder, Gezoogd aan de borst van mijn moeder: Vond ik u buiten, dan kon ik u kussen, En men zou er mij niet om verachten.',
        2: 'Dan leidde ik u naar het huis van mijn moeder, Naar de kamer van haar, die mij baarde; Dan laafde ik u met geurige wijn, Met de most van granaten.',
        3: 'Maar zijn linker moet rusten onder mijn hoofd Zijn rechter houde mij omstrengeld!',
        4: '"Ik bezweer u, Jerusalems dochters, Bij de gazellen en de hinden in het veld: Hoe hebt gij de liefde durven wekken en lokken, Voordat het haar lust?"',
        5: 'Wie stijgt daar op uit de steppe Op haar beminde geleund? Onder de appelboom heb ik uw liefde gewekt: Daar, waar uw moeder u ontving, U baarde met smarten.',
        6: 'Leg mij op uw hart als een zegel, Om uw arm als een band: Want sterk als de dood is de liefde! Onverbiddelijk als het graf is haar gloed, Zij laait op als het flitsende vuur, Haar vlammen zijn vlammen van Jahweh!',
        7: 'Watergolven missen de kracht, Om de liefde te blussen, En stromen verzwelgen haar niet. Al bood iemand ook al zijn schatten, Zelfs zijn paleis voor de liefde, Smadelijk wees men hem af!',
        8: 'Wij hadden een jeugdige zuster, Nog zonder borsten: Wat moesten we met onze zuster doen Wanneer men haar vroeg?',
        9: 'Was zij een muur Dan konden we er een zilveren borstweer op bouwen; Was zij een poort, We sloten haar af met een cederbalk.',
        10: 'Ja, ik wàs een muur, En torens waren mijn borsten: Juist daarom werd ik in zijn ogen Een toegang van vrede!',
        11: 'Salomon heeft een wijngaard in Báal-Hamon, Hij heeft hem onder de hoede van wachters gesteld; Elk moet voor zijn vruchten Duizend zilveren sikkels betalen.',
        12: 'Mijn wijngaard is van mij alleen, En zijn vrucht is voor mij! Die duizend, Salomon, gun ik u, En de wachters tweehonderd.',
        13: 'O gij, die in de lusthof toeft: De vrienden luisteren; Laat mij horen uw stem, Uw wensen vernemen.',
        14: 'Snel, mijn beminde, En doe zoals de gazel, Of het jong van het hert Op de balsembergen!',
    },
}
